import React from 'react';

// ── Seeded RNG ────────────────────────────────────────────────────
function seededRng(id) {
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) {
    h ^= id.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return () => { h ^= h << 13; h ^= h >> 17; h ^= h << 5; return (h >>> 0) / 0xFFFFFFFF; };
}

// ── Colour helpers ────────────────────────────────────────────────
function darken(hex, amt = 0.35) {
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `rgb(${Math.round(r*(1-amt))},${Math.round(g*(1-amt))},${Math.round(b*(1-amt))})`;
}
function lighten(hex, amt = 0.55) {
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `rgb(${Math.min(255,Math.round(r+(255-r)*amt))},${Math.min(255,Math.round(g+(255-g)*amt))},${Math.min(255,Math.round(b+(255-b)*amt))})`;
}
function toVeryDark(hex) {
  // near-black but retains colour hue — for Neuromancer bg
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `rgb(${Math.round(r*0.12+4)},${Math.round(g*0.14+4)},${Math.round(b*0.10+4)})`;
}

// ── Classify book — Neuromancer vs Loeb ───────────────────────────
const NEURO_GENRES = new Set([
  'classics','philosophy','theory','ancient','political theory','critical theory',
  'ancient history','greek','latin','continental philosophy','metaphysics',
  'epistemology','phenomenology','ethics','logic','aesthetics',
]);
const NEURO_AUTHORS = [
  'plato','aristotle','marx','hegel','kant','foucault','nietzsche','hume',
  'descartes','spinoza','leibniz','locke','rousseau','hobbes','wittgenstein',
  'heidegger','sartre','camus','derrida','althusser','lukács','gramsci',
  'socrates','thucydides','herodotus','homer','virgil','cicero','tacitus',
  'marcus aurelius','seneca','epictetus','augustine','aquinas','machiavelli',
  'confucius','laozi','zhuangzi','sun tzu','ibn khaldun','averroes',
];

function isNeuromancerStyle(book) {
  const genre = (book.genre || book.genres?.[0] || '').toLowerCase();
  const author = (book.author || book.author?.[0] || '').toLowerCase();
  if (NEURO_GENRES.has(genre)) return true;
  if (NEURO_AUTHORS.some(a => author.includes(a))) return true;
  // Also check title keywords
  const title = (book.title || book.name || '').toLowerCase();
  const classicTitles = ['republic','iliad','odyssey','aeneid','capital','critique','phenomenology','being','ethics','meditations','symposium','apology','nicomachean','leviathan','discourse','genealogy','discipline'];
  if (classicTitles.some(t => title.includes(t))) return true;
  return false;
}

function hashColor(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) hash = str.charCodeAt(i) + ((hash << 5) - hash);
  const h = Math.abs(hash) % 360;
  return `hsl(${h}, 35%, 45%)`;
}

export function BookSpine({ book, height = 120, onClick, selected }) {
  const color = book.color || hashColor(book.title);
  const style = book.coverStyle || (isNeuromancerStyle(book) ? 'neuromancer': 'loeb');

  const spineWidth = Math.max(18, Math.min(32, Math.floor(((book.pages || 300) / 800) * 36) + 12));

  let bg, textColor;
  if (style === 'neuromancer') {
  bg = toVeryDark(color);
  textColor = lighten(color, 0.72);
  accentBg = 'rgba(255,255,255,0.06)';
}
else if (style === 'loeb') {
  bg = '#f4ecd8';
  textColor = '#3a2e1a';
  accentBg = 'rgba(120,90,40,0.08)';
}
else if (style === 'dark') {
  bg = '#1a1814';
  textColor = 'rgba(255,255,255,0.85)';
  accentBg = 'rgba(255,255,255,0.08)';
}
else if (style === 'minimal') {
  bg = '#f8f6f2';
  textColor = '#2a2820';
  accentBg = 'rgba(0,0,0,0.05)';
}
else if (style === 'warm') {
  bg = '#f5e6cc';
  textColor = '#3a2e1a';
  accentBg = 'rgba(0,0,0,0.06)';
}
else {
  bg = color;
  textColor = 'rgba(255,255,255,0.92)';
  accentBg = 'rgba(255,255,255,0.12)';
}

  return (
    <div
      onClick={onClick}
      title={`${book.title} — ${book.author}`}
      style={{
        width: spineWidth,
        height,
        background: bg,
        borderRadius: '2px 3px 3px 2px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: 'pointer',
        position: 'relative',
        boxShadow: selected
          ? `0 0 0 2px var(--ink), 2px 2px 6px rgba(0,0,0,0.25)`
          : '1px 1px 4px rgba(0,0,0,0.15), inset -1px 0 0 rgba(0,0,0,0.08)',
        transition: 'transform 0.15s, box-shadow 0.15s',
        flexShrink: 0,
      }}
      onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-4px)'; }}
      onMouseLeave={e => { e.currentTarget.style.transform = 'translateY(0)'; }}
    >
      {/* Left edge shadow */}
      <div style={{
        position: 'absolute', left: 0, top: 0, bottom: 0, width: 3,
        background: 'rgba(0,0,0,0.18)', borderRadius: '2px 0 0 2px',
      }} />
      {/* Rotated title */}
      <div style={{
        writingMode: 'vertical-rl',
        textOrientation: 'mixed',
        transform: 'rotate(180deg)',
        fontSize: 9,
        fontWeight: 500,
        color: textColor,
        letterSpacing: '0.03em',
        padding: '4px 2px',
        overflow: 'hidden',
        maxHeight: height - 16,
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap',
        lineHeight: 1.2,
        fontFamily: 'var(--font-serif)',
      }}>
        {book.title}
      </div>
    </div>
  );
}

export function BookCard({ book, status, onClick, selected }) {
  const color = book.color || hashColor(book.title);
  const style = book.coverStyle || (isNeuromancerStyle(book) ? 'Neuromancer' : 'loeb');

  let bg, textColor, accentBg;
  if (style === 'neuromancer') {
  bg = toVeryDark(color);
  textColor = lighten(color, 0.72);
  accentBg = 'rgba(255,255,255,0.06)';
}
else if (style === 'loeb') {
  bg = '#f4ecd8';
  textColor = '#3a2e1a';
  accentBg = 'rgba(120,90,40,0.08)';
}
else if (style === 'dark') {
  bg = '#1a1814';
  textColor = 'rgba(255,255,255,0.85)';
  accentBg = 'rgba(255,255,255,0.08)';
}
else if (style === 'minimal') {
  bg = '#f8f6f2';
  textColor = '#2a2820';
  accentBg = 'rgba(0,0,0,0.05)';
}
else if (style === 'warm') {
  bg = '#f5e6cc';
  textColor = '#3a2e1a';
  accentBg = 'rgba(0,0,0,0.06)';
}
else {
  bg = color;
  textColor = 'rgba(255,255,255,0.92)';
  accentBg = 'rgba(255,255,255,0.12)';
}

  const pct = book.pages ? Math.min(100, Math.round((book.progress / book.pages) * 100)) : 0;

  return (
    <div
      onClick={onClick}
      style={{
        width: 120,
        background: bg,
        borderRadius: 6,
        overflow: 'hidden',
        cursor: 'pointer',
        boxShadow: selected
          ? `0 0 0 2px var(--ink), 3px 4px 12px rgba(0,0,0,0.22)`
          : '2px 3px 10px rgba(0,0,0,0.14)',
        transition: 'transform 0.15s, box-shadow 0.15s',
        position: 'relative',
        flexShrink: 0,
      }}
      onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-4px)'; e.currentTarget.style.boxShadow = '3px 6px 16px rgba(0,0,0,0.22)'; }}
      onMouseLeave={e => { e.currentTarget.style.transform = 'none'; e.currentTarget.style.boxShadow = selected ? `0 0 0 2px var(--ink), 3px 4px 12px rgba(0,0,0,0.22)` : '2px 3px 10px rgba(0,0,0,0.14)'; }}
    >
      {/* Cover face */}
      <div style={{ height: 160, padding: '16px 12px 12px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
        <div>
          <div style={{ fontSize: 11, fontWeight: 600, color: textColor, lineHeight: 1.35, marginBottom: 4, fontFamily: 'var(--font-serif)' }}>
            {book.title}
          </div>
          <div style={{ fontSize: 9, color: textColor, opacity: 0.7, fontStyle: 'italic' }}>{book.author}</div>
        </div>
        {/* Decorative line */}
        <div style={{ height: 1, background: textColor, opacity: 0.2, margin: '8px 0' }} />
        <div style={{ fontSize: 9, color: textColor, opacity: 0.6, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
          {book.year < 0 ? `${Math.abs(book.year)} BCE` : book.year}
        </div>
      </div>

      {/* Progress bar for reading */}
      {book.status === 'reading' && book.pages && (
        <div style={{ height: 3, background: accentBg }}>
          <div style={{ height: '100%', width: `${pct}%`, background: textColor, opacity: 0.6, transition: 'width 0.3s' }} />
        </div>
      )}

      {/* Status ribbon */}
      {status && (
        <div style={{ background: accentBg, padding: '4px 8px', fontSize: 8, color: textColor, opacity: 0.85, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.04em' }}>
          {status.label.toUpperCase()}
        </div>
      )}
    </div>
  );
}
